def answers():
    def f(x):
        x = float(x)
        return int(x) if x == int(x) else round(x, 2)
    import pandas as pd
    s = pd.Series([7.5, None, 6.8, 8.1, None, 5.9, 7.0, 6.4])
    n = int(s.isna().sum())
    return [n, len(s), int(s.count()), f(n / len(s) * 100), f(n / s.count() * 100)]
